const RED: unique symbol = Symbol("red");
const BLUE: unique symbol = Symbol("blue");

type Color = typeof RED | typeof BLUE;

function nameOf(color: Color): string {
  return color === RED ? "red" : "blue";
}

console.log(nameOf(RED));

function parseId(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "number") return String(value);
  throw new TypeError("Expected a string or number");
}

const id = parseId(JSON.parse('"user-42"'));

